import unittest

from invoice import invoice_label, invoice_total


class InvoiceTests(unittest.TestCase):
    def test_totals(self):
        for units, expected in ((-2, -4), (0, 0), (9, 18), (10, 10), (11, 11)):
            with self.subTest(units=units):
                self.assertEqual(invoice_total(units), expected)

    def test_discounts(self):
        self.assertEqual(invoice_total(9, 3), 15)
        self.assertEqual(invoice_total(10, 3), 7)
        self.assertEqual(invoice_total(-2, 3), -7)

    def test_labels(self):
        for units, expected in ((-2, "-2 x 2"), (0, "0 x 2"), (9, "9 x 2"), (10, "10 x 1"), (11, "11 x 1")):
            with self.subTest(units=units):
                self.assertEqual(invoice_label(units), expected)
